import{_ as e,c as r,o as h,af as i}from"./chunks/framework.BKeRpnBD.js";const p=JSON.parse('{"title":"28、【大过】 巽下兑上","description":"横渠易说 - 28、【大过】 巽下兑上","frontmatter":{"title":"28、【大过】 巽下兑上","description":"横渠易说 - 28、【大过】 巽下兑上"},"headers":[],"relativePath":"zh/classics/hengqu/030.md","filePath":"zh/classics/hengqu/030.md"}'),l={name:"zh/classics/hengqu/030.md"};function t(n,a,s,d,c,o){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="_28、【大过】-巽下兑上" tabindex="-1">28、【大过】 巽下兑上 <a class="header-anchor" href="#_28、【大过】-巽下兑上" aria-label="Permalink to “28、【大过】 巽下兑上”">​</a></h1><h3 id="彖曰-大过-大者过也。-栋挠-本末弱也。刚过而中-巽而说行-利有攸往乃亨-大过之时大矣哉" tabindex="-1">彖曰：“大过”，大者过也。“栋挠”，本末弱也。刚过而中，巽而说行，利有攸往乃亨，大过之时大矣哉! <a class="header-anchor" href="#彖曰-大过-大者过也。-栋挠-本末弱也。刚过而中-巽而说行-利有攸往乃亨-大过之时大矣哉" aria-label="Permalink to “彖曰：“大过”，大者过也。“栋挠”，本末弱也。刚过而中，巽而说行，利有攸往乃亨，大过之时大矣哉!”">​</a></h3><h3 id="象曰-泽灭木-大过-君子以独立不惧-遁世无闷。" tabindex="-1">象曰：泽灭木，大过，君子以独立不惧，遁世无闷。 <a class="header-anchor" href="#象曰-泽灭木-大过-君子以独立不惧-遁世无闷。" aria-label="Permalink to “象曰：泽灭木，大过，君子以独立不惧，遁世无闷。”">​</a></h3><p>阳刚过实于中，本末过弱于外，故当过矫相与也。</p><h3 id="初六-藉用白茅-无咎。-象曰-藉用白茅-柔在下也。" tabindex="-1">初六，藉用白茅，无咎。 象曰：“藉用白茅”，柔在下也。 <a class="header-anchor" href="#初六-藉用白茅-无咎。-象曰-藉用白茅-柔在下也。" aria-label="Permalink to “初六，藉用白茅，无咎。 象曰：“藉用白茅”，柔在下也。”">​</a></h3><h3 id="九二-枯杨生稊-老夫得其女妻-无不利。-象曰-老夫女妻-过以相与也。" tabindex="-1">九二，枯杨生稊，老夫得其女妻，无不利。 象曰：老夫女妻，过以相与也。 <a class="header-anchor" href="#九二-枯杨生稊-老夫得其女妻-无不利。-象曰-老夫女妻-过以相与也。" aria-label="Permalink to “九二，枯杨生稊，老夫得其女妻，无不利。 象曰：老夫女妻，过以相与也。”">​</a></h3><p>扶衰于上，使枯木生稊，拯弱于下，使微阴获助，此刚中下济之功，亦自获助于物也。</p><h3 id="九三-栋挠-凶。-象曰-栋挠之凶-不可以有辅也。" tabindex="-1">九三，栋挠，凶。 象曰：栋挠之凶，不可以有辅也。 <a class="header-anchor" href="#九三-栋挠-凶。-象曰-栋挠之凶-不可以有辅也。" aria-label="Permalink to “九三，栋挠，凶。 象曰：栋挠之凶，不可以有辅也。”">​</a></h3><h3 id="九四-栋隆-吉。有它吝。-象曰-栋隆之吉-不挠乎下也。" tabindex="-1">九四，栋隆，吉。有它吝。 象曰：栋隆之吉，不挠乎下也。 <a class="header-anchor" href="#九四-栋隆-吉。有它吝。-象曰-栋隆之吉-不挠乎下也。" aria-label="Permalink to “九四，栋隆，吉。有它吝。 象曰：栋隆之吉，不挠乎下也。”">​</a></h3><p>志在拯弱则栋隆而吉，若私应为心则挠乎下，吝也。</p><h3 id="九五-枯杨生华-老妇得其士夫-无咎无誉。-象曰-枯杨生华-何可久也-老妇士夫-亦可丑也。" tabindex="-1">九五，枯杨生华，老妇得其士夫，无咎无誉。 象曰：“枯杨生华”，何可久也!老妇士夫，亦可丑也。 <a class="header-anchor" href="#九五-枯杨生华-老妇得其士夫-无咎无誉。-象曰-枯杨生华-何可久也-老妇士夫-亦可丑也。" aria-label="Permalink to “九五，枯杨生华，老妇得其士夫，无咎无誉。 象曰：“枯杨生华”，何可久也!老妇士夫，亦可丑也。”">​</a></h3><p>九五上系上六，故不能下济大事，徒益其末耳，无拯物之心，所施者狭。老妇士夫，所与者不足道。枯杨生华，势不能久，故无誉；未至长乱，故无咎。</p><h3 id="上六-过涉灭顶-凶-无咎。-象曰-过涉之凶-不可咎也。" tabindex="-1">上六，过涉灭顶，凶，无咎。 象曰：过涉之凶，不可咎也。 <a class="header-anchor" href="#上六-过涉灭顶-凶-无咎。-象曰-过涉之凶-不可咎也。" aria-label="Permalink to “上六，过涉灭顶，凶，无咎。 象曰：过涉之凶，不可咎也。”">​</a></h3><p>阴居上极，虽过而不足涉难，故凶。大过之极，故灭顶而无咎也。</p>',14)])])}const b=e(l,[["render",t]]);export{p as __pageData,b as default};
